"""Native four-view officer-direction attempt for the fixed C10365 alley cell.

The captured gesture and response are observations. This runner supplies no
finding that the direction was lawful or that the subject acted willfully.
"""
from __future__ import annotations
import argparse,json,math
from pathlib import Path

PREFIX='heldout__C10365__NRS-484B-100__motor_vehicle_driver__'
CASES={
    'stop_responds':('stop',True),
    'stop_does_not_respond':('stop',False),
    'proceed_responds':('proceed',True),
    'proceed_does_not_respond':('proceed',False),
}

def check_config(config):
    if (config.get('law_id'),config.get('cell_id'),config.get('actor'))!=('NRS-484B-100','C10365','motor_vehicle_driver'):
        raise ValueError('Wrong frozen officer-direction scope')
    case=config.get('selected_case_id','')
    suffix=case.removeprefix(PREFIX)
    if case!=PREFIX+suffix or suffix not in CASES or config.get('case',{}).get('case_id')!=case:
        raise ValueError('Unknown exact officer-direction case')
    if config.get('rate_hz')!=20 or config.get('frames')!=160 or len(config.get('cameras',[]))!=4:
        raise ValueError('Four-view 20 Hz capture contract missing')
    if config.get('direction_frame')!=40:
        raise ValueError('Timed indication frame changed')
    if not 10.0<=float(config.get('route_distance_m',18.0))<=18.0:
        raise ValueError('Unsupported connected alley route length')
    if not 0.0<=float(config.get('pose_pitch_delta_deg',0.0))<=20.0:
        raise ValueError('Unsupported officer pose change')
    if not 0.0<=float(config.get('overview_height_delta_m',0.0))<=2.0:
        raise ValueError('Unsupported overview mount change')
    return CASES[suffix]

def choose_alley_route(world_map,*,distance_m=18.0):
    """Select a connected, narrow, nonjunction lane with an officer sidewalk."""
    for spawn in world_map.get_spawn_points():
        lane=world_map.get_waypoint(spawn.location)
        if lane is None or lane.is_junction or not 2.3<=lane.lane_width<=3.5:
            continue
        ahead=lane.next(distance_m)
        if len(ahead)!=1 or ahead[0].is_junction or ahead[0].road_id!=lane.road_id or ahead[0].lane_id!=lane.lane_id:
            continue
        officer=lane.get_right_lane()
        if officer is None or str(officer.lane_type).lower().find('sidewalk')<0:
            continue
        return lane,ahead[0],officer
    raise ValueError('No connected Native alley lane with adjacent officer sidewalk')

def command_for(command,responds,frame,direction_frame):
    """Predeclared physical motion; observed response is measured after capture."""
    if frame<direction_frame:return {'throttle':0.16,'brake':0.0}
    if command=='stop':return {'throttle':0.0,'brake':0.7} if responds else {'throttle':0.16,'brake':0.0}
    return {'throttle':0.18,'brake':0.0} if responds else {'throttle':0.0,'brake':0.7}

def _arm_bone(bones):
    names=[row[0] for row in bones.bone_transforms]
    for marker in ('upperarm_r','upper_arm_r','rightupperarm','r_upperarm','r_arm'):
        matches=[name for name in names if marker in name.lower()]
        if len(matches)==1:return matches[0]
    raise ValueError('Native officer walker has no identifiable right upper-arm bone: '+str(names))

def pose_direction(carla,officer,command,pitch_delta_deg=0.0):
    """Use CARLA's walker bone pose API to create a distinct visible arm cue."""
    bones=officer.get_bones();arm=_arm_bone(bones)
    angle=(95.0 if command=='stop' else 35.0)+pitch_delta_deg
    transform=carla.Transform(carla.Location(),carla.Rotation(pitch=angle))
    officer.set_bones(carla.WalkerBoneControlIn([(arm,transform)]))
    officer.blend_pose(1.0)
    return {'bone':arm,'relative_pitch_deg':angle,'command':command}

def _spawn(world,blueprint,transform):
    actor=world.try_spawn_actor(blueprint,transform)
    if actor is None:raise ValueError('Native officer scene actor spawn failed: '+blueprint.id)
    return actor

def run(output,host,port):
    import carla
    from pipeline_capture import PipelineCapture
    from worker_exchange.native_output import FrameMap,seal_capture
    from officer_camera_capture import CAMERAS,FFmpegSourceSink,OfficerCameraCapture
    output=Path(output);config=json.loads((output/'config.json').read_text());command,responds=check_config(config)
    client=carla.Client(host,port);client.set_timeout(30)
    world=client.get_world();original=world.get_settings();actors=[];sinks={};camera=None;pipeline=None;mapping=None
    frames=[];failed=False;restored=False
    try:
        settings=world.get_settings();settings.synchronous_mode=True;settings.fixed_delta_seconds=.05;world.apply_settings(settings)
        lane,front,sidewalk=choose_alley_route(world.get_map(),distance_m=float(config.get('route_distance_m',18.0)))
        library=world.get_blueprint_library();ego=_spawn(world,library.find('vehicle.tesla.model3'),lane.transform);actors.append(ego)
        walker_blueprints=library.filter('walker.pedestrian.*')
        if not walker_blueprints:raise ValueError('Native officer walker blueprint unavailable')
        officer=_spawn(world,walker_blueprints[0],sidewalk.transform);actors.append(officer)
        officer.apply_control(carla.WalkerControl(speed=0.0))
        for name in CAMERAS:sinks[name]=FFmpegSourceSink(output,name)
        camera=OfficerCameraCapture(world,carla,ego,sinks,
            overview_height_delta_m=float(config.get('overview_height_delta_m',0.0)))
        pipeline=PipelineCapture(client,ego,output,config['selected_case_id'],required_observations=config.get('required_atoms',[]))
        mapping=FrameMap(output/'video_frames.jsonl')
        pose=None;motion=[];direction=None;start=None
        for index in range(config['frames']):
            if index==config['direction_frame']:
                pose=pose_direction(carla,officer,command,float(config.get('pose_pitch_delta_deg',0.0)))
            control=command_for(command,responds,index,config['direction_frame'])
            ego.apply_control(carla.VehicleControl(throttle=control['throttle'],brake=control['brake'],steer=0.0))
            frame=world.tick();snapshot=world.get_snapshot()
            if snapshot.frame!=frame:raise ValueError('Native officer snapshot/frame mismatch')
            if start is None:start=snapshot.timestamp.elapsed_seconds
            time_s=snapshot.timestamp.elapsed_seconds-start
            camera.wait_for_frame(frame)
            trace=pipeline.capture(frame,time_s)
            if trace.get('frame')!=frame or trace.get('time_s')!=time_s:raise ValueError('Original officer trace/frame join differs')
            mapping.append(frame,time_s)
            velocity=ego.get_velocity()
            motion.append({'frame':frame,'time_s':time_s,'subject_id':str(ego.id),'speed_mps':math.hypot(velocity.x,velocity.y),'position_m':[ego.get_location().x,ego.get_location().y,ego.get_location().z]})
            if index==config['direction_frame']:
                direction={'frame':frame,'officer_id':str(officer.id),'subject_id':str(ego.id),'command':command,'indication_source':'original four-view video and walker bone readback','pose':pose}
            frames.append(frame)
        camera.verify_frames(frames)
        if direction is None:raise ValueError('No original officer indication')
        (output/'officer_context.json').write_text(json.dumps({'actor_role':'motor_vehicle_driver','officer_role':'police_officer','officer_id':str(officer.id),'subject_id':str(ego.id),'duty_source':'scenario role assignment; legal review required','lawfulness_source':'original officer indication and independent legal review required','legal_conclusion':None,'willfulness_conclusion':None},indent=2)+'\n')
        (output/'officer_direction.json').write_text(json.dumps(direction,indent=2)+'\n')
        (output/'subject_motion.json').write_text(json.dumps({'frames':motion},indent=2)+'\n')
        (output/'subject_motion_history.jsonl').write_text(''.join(json.dumps(row)+'\n' for row in motion))
    except BaseException:
        failed=True;raise
    finally:
        if mapping:mapping.close()
        if pipeline:pipeline.close(confirmed=not failed)
        if camera:camera.close()
        for sink in sinks.values():sink.close()
        for actor in reversed(actors):actor.destroy()
        world.apply_settings(original)
        current=world.get_settings();restored=current.synchronous_mode==original.synchronous_mode and current.fixed_delta_seconds==original.fixed_delta_seconds
        if not restored:raise ValueError('Native officer settings restoration readback differs')
    (output/'acquisition-provenance.json').write_text(json.dumps({'provenance_kind':'native','diagnostic_fixture':False,'original_frames':len(frames)})+'\n')
    seal_capture(output,frames=len(frames),restoration={'restored':restored},errors=[],encoder_exit_codes={name:0 for name in CAMERAS},context={'native_map_name':world.get_map().name,'road_id':lane.road_id,'officer_actor_id':officer.id})

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');parser.add_argument('--output-dir');parser.add_argument('--host',default='127.0.0.1');parser.add_argument('--port',type=int,default=2000);a=parser.parse_args()
    if a.check:
        check_config(json.loads(Path('config.json').read_text()));return
    if not a.output_dir:parser.error('--output-dir required')
    run(a.output_dir,a.host,a.port)
if __name__=='__main__':main()

"""Four original-frame RGB sources for the officer-direction delivery attempt.

The caller owns the world and encoder sinks. Each sensor is attached to the
subject; a sink must retain its own unscaled source stream under the given name.
This module does not infer officer authority or physical visibility from pixels.
"""
from __future__ import annotations

from dataclasses import dataclass
import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8.0, 0.0, 8.0), (-12.0, 0.0, 0.0), (1920, 1080), 95),
    "approach": ((1.2, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    "reference_corner": ((-3.0, 2.5, 2.6), (-7.0, 0.0, 0.0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0.0, 0.0, 0.0), (1280, 720), 85),
}


@dataclass(frozen=True)
class CameraPlan:
    name: str
    location: tuple[float, float, float]
    rotation: tuple[float, float, float]
    size: tuple[int, int]
    fov: int


def plans(overview_height_delta_m=0.0):
    if not 0.0<=overview_height_delta_m<=2.0:
        raise ValueError('Unsupported overview mount change')
    result=[]
    for name,spec in CAMERAS.items():
        location,rotation,size,fov=spec
        if name=='overview':
            location=(location[0],location[1],location[2]+overview_height_delta_m)
        result.append(CameraPlan(name,location,rotation,size,fov))
    return result


class FFmpegSourceSink:
    """Retain one lossless, original-resolution BGRA stream from CARLA images."""

    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source stream; use a fresh attempt")
        width, height = CAMERAS[name][2]
        self.size = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed:
            raise ValueError("Source stream already closed")
        raw = image.raw_data
        if len(raw) != self.size:
            raise ValueError("Source camera raw byte count changed")
        self.process.stdin.write(raw)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Source camera encoder failed")


class OfficerCameraCapture:
    def __init__(self, world, carla_module, subject, sinks, overview_height_delta_m=0.0):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named source-camera sinks are required")
        self.sensors = {}
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.callback_errors = []
        self.closed = False
        library = world.get_blueprint_library()
        try:
            for plan in plans(overview_height_delta_m):
                bp = library.find("sensor.camera.rgb")
                for key, value in (("image_size_x", plan.size[0]),
                                   ("image_size_y", plan.size[1]),
                                   ("fov", plan.fov), ("sensor_tick", 0.05)):
                    bp.set_attribute(key, str(value))
                loc = carla_module.Location(*plan.location)
                pitch, yaw, roll = plan.rotation
                transform = carla_module.Transform(loc, carla_module.Rotation(pitch, yaw, roll))
                sensor = world.spawn_actor(bp, transform, attach_to=subject)
                self.sensors[plan.name] = sensor
                sensor.listen(lambda image, name=plan.name: self._on_frame(name, image))
        except BaseException:
            self.close()
            raise

    def _on_frame(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame: " + name)
                expected = CAMERAS[name][2]
                if (image.width, image.height) != expected:
                    raise ValueError("Source camera dimensions changed: " + name)
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.callback_errors.append(error)
                raise
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        """Join all original source pixels before writing that Native tick."""
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.callback_errors:
                    raise ValueError("Source camera callback failed") from self.callback_errors[0]
                if all(frame in rows for rows in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    missing = sorted(name for name, rows in self.frames.items() if frame not in rows)
                    raise ValueError("Timed out waiting for source camera frame "
                                     + str(frame) + ": " + ", ".join(missing))
                self.condition.wait(remaining)

    def verify_frames(self, frames):
        if self.callback_errors:
            raise ValueError("Source camera callback failed") from self.callback_errors[0]
        expected = set(frames)
        if not expected:
            raise ValueError("No captured original frames")
        for name, observed in self.frames.items():
            if observed != expected:
                raise ValueError("Missing or extra source-camera frames: " + name)
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()
                sensor.destroy()

"""Source-bound observation of response to an officer's timed direction.

This records motion only. Officer authority, lawful order and willfulness remain
independent source and legal review questions.
"""
from __future__ import annotations
import json
from pathlib import Path


def _load(path):
    p = Path(path)
    if not p.is_file():
        raise ValueError("missing required source: " + str(p))
    return json.loads(p.read_text())


def measure(context_path, direction_path, motion_path, *, expected_actor, expected_command):
    context, direction, motion = (_load(p) for p in (context_path, direction_path, motion_path))
    if context.get("actor_role") != expected_actor:
        raise ValueError("actor role differs from exact case")
    if context.get("officer_role") != "police_officer" or not context.get("officer_id"):
        raise ValueError("officer role or identity missing")
    if not context.get("duty_source") or not context.get("lawfulness_source"):
        raise ValueError("officer duty and order-lawfulness source references required")
    if context.get("legal_conclusion") or context.get("willfulness_conclusion"):
        raise ValueError("fixture may not assert legal or willfulness conclusion")
    if direction.get("officer_id") != context["officer_id"] or direction.get("subject_id") != context.get("subject_id"):
        raise ValueError("direction is not source-bound to this officer and subject")
    if direction.get("command") != expected_command or expected_command not in ("stop", "proceed"):
        raise ValueError("direction differs from exact case")
    frame = direction.get("frame")
    if type(frame) is not int or frame < 0 or not direction.get("indication_source"):
        raise ValueError("timed officer indication source missing")
    rows = motion.get("frames")
    if not isinstance(rows, list) or len(rows) < 3:
        raise ValueError("retained subject motion span missing")
    indices = [r.get("frame") for r in rows]
    if any(type(i) is not int for i in indices) or indices != sorted(set(indices)):
        raise ValueError("motion frame identities must be unique and ordered")
    if not (indices[0] <= frame < indices[-1]):
        raise ValueError("motion does not bracket direction and response")
    if any(r.get("subject_id") != context["subject_id"] for r in rows):
        raise ValueError("motion subject differs from direction subject")
    if any(type(r.get("speed_mps")) not in (int, float) or r["speed_mps"] < 0 for r in rows):
        raise ValueError("invalid original subject speed sample")
    following = [r for r in rows if r["frame"] > frame]
    if len(following) < 2:
        raise ValueError("at least two post-indication motion samples required")
    # Descriptive engineering observation, not a legal compliance threshold.
    stopped = any(r["speed_mps"] <= 0.1 for r in following)
    moving = any(r["speed_mps"] > 0.5 for r in following)
    if expected_command == "stop":
        response = "stopped_after_indication" if stopped else "no_observed_stop"
    else:
        response = "moved_after_indication" if moving else "no_observed_movement"
    return {"actor_role": expected_actor, "subject_id": context["subject_id"],
            "officer_id": context["officer_id"], "command": expected_command,
            "indication_frame": frame, "first_motion_frame": indices[0],
            "last_motion_frame": indices[-1], "post_indication_samples": len(following),
            "min_post_speed_mps": min(r["speed_mps"] for r in following),
            "max_post_speed_mps": max(r["speed_mps"] for r in following),
            "observed_response": response,
            "source_refs": [str(context_path), str(direction_path), str(motion_path)],
            "legal_conclusion": None, "willfulness_conclusion": None}


def main():
    import argparse
    ap=argparse.ArgumentParser()
    ap.add_argument("--context",required=True)
    ap.add_argument("--direction",required=True)
    ap.add_argument("--motion",required=True)
    ap.add_argument("--actor",required=True)
    ap.add_argument("--command",choices=("stop","proceed"),required=True)
    ap.add_argument("--output",required=True)
    a=ap.parse_args()
    result=measure(a.context,a.direction,a.motion,expected_actor=a.actor,expected_command=a.command)
    Path(a.output).write_text(json.dumps(result,indent=2)+"\n")
if __name__ == "__main__": main()

"""Saved-only, source-bound officer-direction and observed-response finalizer."""
from __future__ import annotations
import argparse,hashlib,json
from pathlib import Path
from officer_response import measure
from officer_native_runner import check_config

def source(root,name):
    path=Path(root)/name
    if not path.is_file() or not path.read_bytes():raise ValueError('Missing required source: '+name)
    return path

def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def rows(path):return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]

def measure_officer(context,direction,motion,command):
    """Named exact-contract source measurement without a legal verdict."""
    return measure(context,direction,motion,expected_actor='motor_vehicle_driver',expected_command=command)

def analyze(root):
    root=Path(root);cfg=json.loads(source(root,'config.json').read_text());command,_=check_config(cfg)
    context=source(root,'officer_context.json');direction=source(root,'officer_direction.json');motion=source(root,'subject_motion.json')
    observed=measure_officer(context,direction,motion,command)
    mapping=rows(source(root,'video_frames.jsonl'));trace=rows(source(root,'trace.jsonl'))
    history=rows(source(root,'subject_motion_history.jsonl'))
    if len(mapping)<3 or len(mapping)!=len(trace) or len(trace)!=len(history):
        raise ValueError('Original officer frame-map, trace and motion lengths differ')
    for index,(fm,t,h) in enumerate(zip(mapping,trace,history)):
        if (fm.get('video_frame')!=index or fm.get('carla_frame')!=t.get('frame') or t.get('frame')!=h.get('frame')
                or fm.get('time_s')!=t.get('time_s') or t.get('time_s')!=h.get('time_s')
                or h.get('subject_id')!=observed['subject_id']):
            raise ValueError('Original officer frame join differs')
    if observed['indication_frame'] not in {h['frame'] for h in history}:
        raise ValueError('Timed original indication absent from frame map')
    joined={h['frame']:h for h in history}
    raw_motion=json.loads(motion.read_text())['frames']
    if raw_motion!=history:raise ValueError('Original officer motion JSON and JSONL differ')
    channels={
        'subject_speed_mps':[(h['frame'],h['time_s'],h['speed_mps']) for h in history],
        'officer_direction':[(h['frame'],h['time_s'],1 if h['frame']>=observed['indication_frame'] else 0) for h in history],
    }
    for name,data in channels.items():
        (root/(name+'.jsonl')).write_text(''.join(json.dumps({'frame':f,'time_s':t,'value':v})+'\n' for f,t,v in data))
    sources={name:sha(source(root,name)) for name in ('officer_context.json','officer_direction.json','subject_motion.json','subject_motion_history.jsonl','video_frames.jsonl','trace.jsonl')}
    return {'format':'worker-analysis-report','case_id':cfg['selected_case_id'],
            'measurements':{'officer_response':{'method':'measure_officer','value':observed,'sources':sources}},
            'legal_acceptance_claimed':False,'physical_acceptance_claimed':False}

def result(root,report):
    root=Path(root);cfg=json.loads((root/'config.json').read_text());observed=report['measurements']['officer_response']['value']
    contexts=[]
    for name,reference in (('officer_context','officer_context.json'),
                           ('officer_direction_context','officer_direction.json'),
                           ('subject_motion_context','subject_motion.json'),
                           ('subject_motion_history','subject_motion_history.jsonl')):
        original=root/reference
        value=rows(original) if original.suffix=='.jsonl' else json.loads(original.read_text())
        derived=root/(name+'-recorded.json')
        if derived.exists():raise ValueError('Retain prior derived officer context')
        derived.write_text(json.dumps({name:value})+'\n')
        contexts.append({'name':name,'unit':'structured record',
                         'reference':derived.name,'sha256':sha(derived)})
    return {'case_id':report['case_id'],'measured_values':{'officer_response':observed},
            'target_checks':[{'target':'timed officer indication and observable response','requested':cfg['case']['intended_observed_response'],
                              'measured':observed['observed_response'],'method':'source-bound indication and post-indication original motion',
                              'tolerance':None,'matched':observed['observed_response']==cfg['case']['intended_observed_response'],
                              'physical_cause_confirmed':False,'cause_evidence':'Original gesture and subject motion; lawful duty and willfulness need independent review'}],
            'setup_confirmed':False,'behavior_attempted':True,'maneuver_completed':False,
            'termination_reason':'Saved source measurement complete; physical and legal outcome unverified',
            'physical_failure_flags':{'gesture_visibility_unverified':True,'officer_authority_unverified':True},
            'trace_reference':'trace.jsonl','video_references':['overview.mkv','approach.mkv','reference_corner.mkv','driver_reference.mkv'],
            'video_frame_map_reference':'video_frames.jsonl','recording_description':cfg['case']['recording_description'],
            'recording_evidence':[
                *[{'name':name,'unit':unit,'reference':name+'.jsonl','sha256':sha(root/(name+'.jsonl'))}
                  for name,unit in (('subject_speed_mps','m/s'),('officer_direction','boolean'))],
                *contexts],
            'realized_observables':{'subject_speed_mps':{'unit':'m/s','method':'original subject velocity sampled after indication',
                                  'time_window':'post-indication original frames','statistic':'min',
                                  'reference':'subject_speed_mps.jsonl','value':observed['min_post_speed_mps'],
                                  'sample_window_s':[0,(observed['last_motion_frame']-observed['indication_frame'])/20]},
                                    'officer_direction':{'unit':'boolean','method':'original walker pose activation at indication frame',
                                  'time_window':'all original frames','statistic':'event','reference':'officer_direction.jsonl',
                                  'value':1,'sample_window_s':[0,(observed['last_motion_frame']-observed['first_motion_frame'])/20]}},
            'physical_acceptance_claimed':False,'legal_acceptance_claimed':False}

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',required=True);parser.add_argument('--output',required=True);a=parser.parse_args()
    report=analyze(a.attempt);out=Path(a.output)
    if out.exists():raise ValueError('Retain prior analysis report')
